WITH daily_agg AS ( SELECT cr.cr_returned_date_sk AS return_date, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_return_quantity) AS total_return_qty, cp.cp_department, r.r_reason_desc, SUM(CASE WHEN cd.cd_gender = 'F' THEN 1 ELSE 0 END) AS female_cnt, COUNT(*) AS total_cnt FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk JOIN customer_demographics cd ON cr.cr_returning_cdemo_sk = cd.cd_demo_sk GROUP BY cr.cr_returned_date_sk, cp.cp_department, r.r_reason_desc HAVING SUM(cr.cr_return_quantity) > 10 ) SELECT return_date, total_return_amount, total_return_qty, cp_department, r_reason_desc, female_cnt, total_cnt, CAST(female_cnt AS double) / total_cnt AS female_ratio, ROW_NUMBER() OVER (ORDER BY total_return_amount DESC) AS amount_rank, SUM(total_return_amount) OVER (ORDER BY return_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount FROM daily_agg ORDER BY amount_rank LIMIT 20
